### Intelligens token routing (költségoptimalizálás)

```javascript
class IntelligentRouter {
    constructor() {
        this.dailyUsage = {
            cerebras: 0,
            groq: 0,
            gemini: 0
        };

        this.limits = {
            cerebras: 1000000,  // 1M/day
            groq: 500000,       // 500K/day
            gemini: 250000      // estimált alapján RPD
        };
    }

    async routeRequest(prompt, taskType) {
        const estimatedTokens = this.estimateTokens(prompt);

        // Prioritás: Cerebras (legbőkezűbb) → Groq → Gemini → OpenRouter free
        if (this.dailyUsage.cerebras + estimatedTokens < this.limits.cerebras) {
            return await this.callCerebras(prompt, taskType);
        }

        if (this.dailyUsage.groq + estimatedTokens < this.limits.groq) {
            return await this.callGroq(prompt, taskType);
        }

        if (this.dailyUsage.gemini + estimatedTokens < this.limits.gemini) {
            return await this.callGemini(prompt, taskType);
        }

        // Fallback: OpenRouter free modellek
        return await this.callOpenRouter(prompt, taskType, true);
    }

    estimateTokens(text) {
        // Durva becslés: ~1.3 token/szó
        return Math.ceil(text.split(/\s+/).length * 1.3);
    }
}
```

